import UIKit
import SwiftUI

/// The little pixel-art mascot shown at the top of the home screen,
/// embedded as base64 PNG data directly in source (same trick as
/// CamswapScript.swift) so no Xcode asset catalog needs to be wired up
/// in project.yml/XcodeGen — one less thing that can silently not get
/// bundled by the CI build.
enum HomeIcon {
    static let base64: String = """

"""

    static var uiImage: UIImage? {
        guard let data = Data(base64Encoded: base64) else { return nil }
        return UIImage(data: data)
    }

    /// SwiftUI Image, falling back to the old SF Symbol if decoding
    /// ever somehow fails (should never happen — verified at build time
    /// by the script that generated this file).
    static var image: Image {
        if let uiImage {
            return Image(uiImage: uiImage).renderingMode(.original)
        }
        return Image(systemName: "video.fill")
    }
}
